public final class ExpertContractCheck {
 private static int checks;
 private static void check(boolean value){checks++;if(!value)throw new AssertionError("check "+checks);}
 private static int word(String s){byte[] b=s.getBytes(StandardCharsets.US_ASCII);return ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN).getInt();}
 private static Object[] read(DataInputStream in)throws Exception {byte[] head=new byte[24];in.readFully(head);ByteBuffer b=ByteBuffer.wrap(head).order(ByteOrder.LITTLE_ENDIAN);int c=b.getInt(),a=b.getInt(),d=b.getInt(),n=b.getInt(),sum=b.getInt(),magic=b.getInt();if(magic!=(c^0xffffffff)||n<0||n>4096)throw new AssertionError("frame");byte[] data=new byte[n];in.readFully(data);int actual=0;for(byte value:data)actual+=value&255;if(actual!=sum)throw new AssertionError("checksum");return new Object[]{c,a,d,data};}
 private static void send(OutputStream out,String command,int a,int b,byte[] data,int corrupt)throws Exception {int sum=corrupt;for(byte value:data)sum+=value&255;int c=word(command);ByteBuffer h=ByteBuffer.allocate(24).order(ByteOrder.LITTLE_ENDIAN);h.putInt(c).putInt(a).putInt(b).putInt(data.length).putInt(sum).putInt(~c);out.write(h.array());out.write(data);out.flush();}
 private static BigInteger little(byte[] b,int start,int length){byte[] reversed=new byte[length];for(int n=0;n<length;n++)reversed[n]=b[start+length-1-n];return new BigInteger(1,reversed);}
 public static void main(String[] args)throws Exception {
  for(String invalid:new String[]{"com.a;reboot","com.a$(id)","com.a\ncom.b","com.a'","--user 10","com.a b","android"}){boolean failed=false;try{SystemCommands.mutation(SystemCommands.Operation.REMOVE,invalid,0);}catch(IllegalArgumentException expected){failed=true;}check(failed);}
  for(SystemCommands.Operation op:SystemCommands.Operation.values()){String command=SystemCommands.mutation(op,"com.example.safe",10);check(command.contains("--user 10 com.example.safe"));check(!command.contains("/system"));check(SystemCommands.query(op,"com.example.safe",10).contains("--user 10"));}
  check(SystemCommands.mutation(SystemCommands.Operation.REMOVE,"com.example.safe",0).contains("uninstall -k"));check(SystemCommands.confirmed(SystemCommands.Operation.DISABLE,"com.example.safe","package:com.example.safe\r\n"));check(!SystemCommands.confirmed(SystemCommands.Operation.ENABLE,"com.example.safe","package:com.example.safe.extra"));check(SystemCommands.confirmed(SystemCommands.Operation.REMOVE,"com.example.safe",""));boolean failed=false;try{SystemCommands.confirmed(SystemCommands.Operation.REMOVE,"com.example.safe","Error: permission denied");}catch(IllegalArgumentException expected){failed=true;}check(failed);
  for(String invalid:new String[]{"x:0","x:65536","x:22;reboot","x y:22","::1:5555"}){failed=false;try{AdbWire.endpoint(invalid);}catch(RuntimeException expected){failed=true;}check(failed);}check(AdbWire.endpoint("[::1]:5555")[0].equals("::1"));
  ShellReply reply=RootCommand.execute(new String[]{"sh","-c","printf 'denied'; exit 7"},2000);check(reply.code==7&&reply.text.equals("denied"));failed=false;try{RootCommand.execute(new String[]{"sh","-c","while :; do :; done"},100);}catch(IOException expected){failed=true;}check(failed);
  KeyPairGenerator gen=KeyPairGenerator.getInstance("RSA");gen.initialize(2048);KeyPair keys=gen.generateKeyPair();AtomicReference<Throwable> error=new AtomicReference<>();ServerSocket listener=new ServerSocket(0,1,InetAddress.getLoopbackAddress());Thread server=new Thread(()->{try(Socket socket=listener.accept()){socket.setSoTimeout(5000);DataInputStream in=new DataInputStream(socket.getInputStream());OutputStream out=socket.getOutputStream();Object[] first=read(in);if((int)first[0]!=word("CNXN"))throw new AssertionError("hello");byte[] token=new byte[20];Arrays.fill(token,(byte)71);send(out,"AUTH",1,0,token,0);Object[] signed=read(in);Signature verifier=Signature.getInstance("NONEwithRSA");verifier.initVerify(keys.getPublic());verifier.update(new byte[]{0x30,0x21,0x30,0x09,0x06,0x05,0x2b,0x0e,0x03,0x02,0x1a,0x05,0,0x04,0x14});verifier.update(token);if(!verifier.verify((byte[])signed[3]))throw new AssertionError("AUTH signature");send(out,"AUTH",1,0,token,0);Object[] offered=read(in);String encoded=new String((byte[])offered[3],StandardCharsets.UTF_8).split(" ")[0];byte[] publicKey=Base64.getDecoder().decode(encoded);RSAPublicKey rsa=(RSAPublicKey)keys.getPublic();if(publicKey.length!=524||!little(publicKey,8,256).equals(rsa.getModulus())||!little(publicKey,520,4).equals(rsa.getPublicExponent()))throw new AssertionError("AUTH key");BigInteger base=BigInteger.ONE.shiftLeft(32);if(!little(publicKey,4,4).multiply(rsa.getModulus().mod(base)).mod(base).equals(base.subtract(BigInteger.ONE)))throw new AssertionError("n0inv");send(out,"CNXN",0x01000000,4096,"device::\0".getBytes(StandardCharsets.UTF_8),0);
   for(int command=1;command<=2;command++){Object[] opened=read(in);int local=(int)opened[1];if(local!=command|| (int)opened[0]!=word("OPEN"))throw new AssertionError("channel");String text=new String((byte[])opened[3],StandardCharsets.UTF_8);Matcher marker=Pattern.compile("__TRUE_TV_[a-f0-9]+__").matcher(text);if(!marker.find())throw new AssertionError("exit wrapper");send(out,"OKAY",40+command,local,new byte[0],0);send(out,"WRTE",40+command,local,"hello\r\n".getBytes(StandardCharsets.UTF_8),0);if((int)read(in)[0]!=word("OKAY"))throw new AssertionError("ACK");send(out,"WRTE",40+command,local,(marker.group()+(command==1?"0":"7")+"\r\n").getBytes(StandardCharsets.UTF_8),0);read(in);send(out,"CLSE",40+command,local,new byte[0],0);if((int)read(in)[0]!=word("CLSE"))throw new AssertionError("close");if(command==1){send(out,"CLSE",0,local,new byte[0],0);send(out,"OKAY",40+command,local,new byte[0],0);}}
  }catch(Throwable e){error.set(e);}},"fake-adbd");server.start();try(AdbWire wire=new AdbWire("127.0.0.1:"+listener.getLocalPort(),keys)){reply=wire.shell("id -u");check(reply.code==0&&reply.text.equals("hello"));reply=wire.shell("false");check(reply.code==7&&reply.text.equals("hello"));}server.join(6000);listener.close();check(!server.isAlive()&&error.get()==null);
  System.out.println("PASS "+checks+" expert command/RSA/ADB framing/late-close isolation/root-runner checks");
 }
}
